-- Provisio / Freshline — per-language product descriptions, mirroring
-- migration 0026's pattern for product names: `description` stays the
-- Russian source of truth, these three are optional overrides the app
-- picks between based on the shopper's selected language (falls back to
-- Russian when a translation is missing, same graceful degradation).
alter table products
  add column if not exists description_uz_cyrl text,
  add column if not exists description_uz_latn text,
  add column if not exists description_en text;

comment on column products.description_uz_cyrl is 'Uzbek (Cyrillic) description override; null falls back to description.';
comment on column products.description_uz_latn is 'Uzbek (Latin) description override; null falls back to description.';
comment on column products.description_en is 'English description override; null falls back to description.';

update products as p
set
  description_uz_cyrl = v.uz_cyrl,
  description_uz_latn = v.uz_latn,
  description_en = v.en
from (values
  ('BC-0001', 'Уруғли хрустли италян нон таёқчалари — пишлоқ ва винога газак.', 'Urugʻli xrustli italyan non tayoqchalari — pishloq va vinoga gazak.', 'Crunchy Italian breadsticks with seeds — a snack for cheese and wine.'),
